import os

os.environ.setdefault("DATABASE_URL", "sqlite://")

import pytest
from fastapi.testclient import TestClient
from sqlalchemy import create_engine, func, select
from sqlalchemy.orm import Session
from sqlalchemy.pool import StaticPool

from api.main import app
from api.routers.auth.auth import require_user
from database.database import get_db
from database.models.user.user import User


@pytest.fixture
def user_client(monkeypatch):
    monkeypatch.setenv("AUTH_REQUIRED", "0")
    engine = create_engine(
        "sqlite://", connect_args={"check_same_thread": False}, poolclass=StaticPool
    )
    User.__table__.create(engine)
    with Session(engine) as db:
        def database():
            yield db

        app.dependency_overrides[get_db] = database
        try:
            with TestClient(app) as client:
                yield client, db
        finally:
            app.dependency_overrides.pop(get_db, None)
            app.dependency_overrides.pop(require_user, None)
    engine.dispose()


def test_repeated_requests_reuse_user_and_ignore_supplied_identity(user_client):
    client, db = user_client
    first = client.post("/api/user/store-user")
    second = client.post("/api/user/store-user", json={"sub": "someone-else"})
    assert first.status_code == second.status_code == 200
    assert first.json() == second.json()
    assert db.scalar(select(func.count()).select_from(User)) == 1
    assert db.scalar(select(User.cognito_subject)) == "local-development"


def test_distinct_identities_and_email_update(user_client):
    client, db = user_client
    identity = {"sub": "first", "email": "first@cmich.edu"}
    app.dependency_overrides[require_user] = lambda: dict(identity)
    first = client.post("/api/user/store-user").json()
    identity["email"] = "updated@cmich.edu"
    updated = client.post("/api/user/store-user").json()
    assert updated == {"id": first["id"], "email": "updated@cmich.edu"}
    identity.update(sub="second", email="second@cmich.edu")
    second = client.post("/api/user/store-user").json()
    assert second["id"] != first["id"]
    assert db.scalar(select(func.count()).select_from(User)) == 2


def test_production_requires_session_before_creating_user(user_client, monkeypatch):
    client, db = user_client
    monkeypatch.setenv("AUTH_REQUIRED", "1")
    monkeypatch.setenv("APP_ORIGIN", "https://cats.example")
    monkeypatch.setenv("COGNITO_REGION", "us-east-2")
    monkeypatch.setenv("COGNITO_USER_POOL_ID", "test-pool")
    monkeypatch.setenv("COGNITO_CLIENT_ID", "test-client")
    monkeypatch.setenv("COGNITO_DOMAIN", "https://login.example")
    response = client.post(
        "/api/user/store-user", headers={"origin": "https://cats.example"}
    )
    assert response.status_code == 401
    assert db.scalar(select(func.count()).select_from(User)) == 0
